-- E0 ONLY (sandbox): objects that 016 relies on, with the definitions read from dwh on the server on
-- 13.11.2026 (database/diagnostics/i17_step3_ai_package.sql): app.permission (all columns), roles and their
-- history, app.auth_get_permissions (same text), app.auth_session, app.user_account, schema dm with
-- dm.v_retail_application_current (a part of its columns), schema ACL and default privileges as in dwh.
-- app.v_user_effective_permission was not read: modelled as current role assignments. Never run against dwh.
-- Run as a superuser in an empty database; objects are owned by dwh_admin.
SET ROLE dwh_admin;
REVOKE ALL ON SCHEMA public FROM PUBLIC;
CREATE SCHEMA app;
CREATE SCHEMA meta;
CREATE SCHEMA dm;
CREATE SCHEMA etl;
GRANT USAGE ON SCHEMA app TO dwh_app;
GRANT USAGE ON SCHEMA meta TO dwh_app, dwh_etl;
GRANT USAGE ON SCHEMA dm TO dwh_app, dwh_etl, dwh_report;
GRANT USAGE ON SCHEMA etl TO dwh_app, dwh_etl;
ALTER DEFAULT PRIVILEGES IN SCHEMA meta GRANT SELECT ON TABLES TO dwh_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA meta GRANT INSERT, SELECT, UPDATE, DELETE, TRUNCATE ON TABLES TO dwh_etl;
ALTER DEFAULT PRIVILEGES IN SCHEMA meta GRANT SELECT, UPDATE, USAGE ON SEQUENCES TO dwh_etl;
ALTER DEFAULT PRIVILEGES IN SCHEMA dm GRANT SELECT ON TABLES TO dwh_app, dwh_report;
ALTER DEFAULT PRIVILEGES IN SCHEMA dm GRANT INSERT, SELECT, UPDATE, DELETE, TRUNCATE ON TABLES TO dwh_etl;
ALTER DEFAULT PRIVILEGES IN SCHEMA dm GRANT SELECT, UPDATE, USAGE ON SEQUENCES TO dwh_etl;

CREATE TABLE app.user_account (user_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username text NOT NULL UNIQUE,
  account_level text NOT NULL, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE app.auth_session (token_hash text PRIMARY KEY, user_id bigint NOT NULL REFERENCES app.user_account(user_id),
  revoked_at timestamptz, expires_at timestamptz NOT NULL);
CREATE TABLE app.permission (permission_id bigint NOT NULL, permission_code text NOT NULL, permission_name text NOT NULL,
  permission_group text NOT NULL, is_assignable boolean NOT NULL DEFAULT true, is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT permission_pkey PRIMARY KEY (permission_id),
  CONSTRAINT ck_permission_code CHECK (permission_code ~ '^[A-Z][A-Z0-9_]*$'));
CREATE TABLE app.role (role_id bigint NOT NULL PRIMARY KEY, role_code text NOT NULL, role_name text NOT NULL,
  description text, is_system boolean NOT NULL DEFAULT false, is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(), created_by_user_id bigint, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.user_role_history (user_role_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id bigint NOT NULL, role_id bigint NOT NULL REFERENCES app.role(role_id), valid_from timestamptz NOT NULL DEFAULT now(),
  valid_to timestamptz, granted_by_user_id bigint, revoked_by_user_id bigint, change_reason text);
CREATE TABLE app.role_permission_history (role_permission_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  role_id bigint NOT NULL REFERENCES app.role(role_id),
  permission_id bigint NOT NULL REFERENCES app.permission(permission_id),
  valid_from timestamptz NOT NULL DEFAULT now(), valid_to timestamptz,
  granted_by_user_id bigint REFERENCES app.user_account(user_id), revoked_by_user_id bigint REFERENCES app.user_account(user_id),
  change_reason text, CONSTRAINT ck_role_permission_period CHECK (valid_to IS NULL OR valid_to > valid_from));
CREATE VIEW app.v_user_effective_permission AS
  SELECT DISTINCT ur.user_id, p.permission_code, p.permission_name, p.permission_group
    FROM app.user_role_history ur
    JOIN app.role r ON r.role_id = ur.role_id AND r.is_active
    JOIN app.role_permission_history rp ON rp.role_id = r.role_id AND rp.valid_to IS NULL
    JOIN app.permission p ON p.permission_id = rp.permission_id AND p.is_active AND p.is_assignable
   WHERE ur.valid_to IS NULL;
CREATE FUNCTION app.auth_get_permissions(p_user_id bigint)
 RETURNS TABLE(permission_code text, permission_name text, permission_group text)
 LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog', 'app' AS $function$
  SELECT p.permission_code, p.permission_name, p.permission_group FROM app.permission p
   WHERE p.is_active = true
     AND EXISTS (SELECT 1 FROM app.user_account u WHERE u.user_id = p_user_id AND u.is_active = true
                  AND u.account_level IN ('SUPERADMIN', 'ADMIN'))
  UNION
  SELECT ep.permission_code, ep.permission_name, ep.permission_group FROM app.v_user_effective_permission ep
   WHERE ep.user_id = p_user_id
  ORDER BY permission_code;
$function$;
GRANT EXECUTE ON FUNCTION app.auth_get_permissions(bigint) TO dwh_app;
INSERT INTO app.user_account (username, account_level) VALUES ('admin', 'SUPERADMIN'), ('user', 'USER');
INSERT INTO app.permission (permission_id, permission_code, permission_name, permission_group) VALUES
  (1, 'ADMIN_INTEGRATION_MANAGE', 'Integration administration', 'ADMIN'),
  (2, 'REPORT_VIEW', 'Reports', 'REPORTING'),
  (3, 'ETL_VIEW', 'ETL runs', 'ETL');

CREATE TABLE dm.retail_application_history (
  dm_application_version_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, application_id bigint,
  application_no varchar(255), application_date date, stage_name_ru varchar(255), status_name_ru varchar(255),
  branch_name_ru varchar(255), sales_channel_code varchar(255), sales_channel_name_ru varchar(255),
  requested_amount numeric, requested_product_name_ru varchar(255), requested_currency_code varchar(255),
  final_amount numeric, final_product_name_ru varchar(255), applicant_total_income numeric, is_current boolean);
CREATE VIEW dm.v_retail_application_current AS
  SELECT * FROM dm.retail_application_history WHERE is_current;
CREATE VIEW dm.v_retail_application_source AS
  SELECT application_id, application_no FROM dm.retail_application_history;
-- A second reporting table (stands for a restricted one such as a salary project).
CREATE TABLE dm.salary_project_stub (employee_no text, salary numeric);
RESET ROLE;
